import { isRecord } from './isRecord.js';
import { readOwnProperty } from './readOwnProperty.js';

/*** Compare unknown values recursively using structural equality for arrays and records. */
export function isDeepEqual(left: unknown, right: unknown): boolean {
  if (left === right) return true;
  if (
    typeof left === 'number' &&
    typeof right === 'number' &&
    Number.isNaN(left) &&
    Number.isNaN(right)
  ) {
    return true;
  }

  if (Array.isArray(left) || Array.isArray(right)) {
    return (
      Array.isArray(left) &&
      Array.isArray(right) &&
      left.length === right.length &&
      left.every((value, index) => isDeepEqual(value, right.at(index)))
    );
  }

  if (!isRecord(left) || !isRecord(right)) return false;

  const leftEntries = Object.entries(left);
  if (leftEntries.length !== Object.keys(right).length) return false;

  return leftEntries.every(
    ([key, value]) => Object.hasOwn(right, key) && isDeepEqual(value, readOwnProperty(right, key)),
  );
}
